/*
 * A259159  Positive squares (A000290) that are heptagonal numbers (A000566)
 *          divided by 2.
 * https://oeis.org/A259159
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) is the square of the n‑th solution y of the Pell equation
 *            x^2 - 80 y^2 = 9 with x ≡ 7 (mod 10). The sequence starts with y
 *            = 3, 969, 312015, ... and a(n) = y^2. The solutions are
 *            generated by iterating the fundamental unit (9 + √80) and
 *            keeping every second step
 * Range:     u8 n <= 1, u16 n <= 1, u32 n <= 2, u64 n <= 4, u128 n <= 8,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Note: no external headers other than <stdlib.h> are required. */
#include <stdlib.h>
#include <stdint.h>

static seq_t *cache = NULL;          /* cached sequence values a(1)...a(max_n)   */
static size_t cache_cap = 0;         /* allocated capacity of cache            */
static size_t cache_len = 0;         /* number of values currently stored      */
static seq_t cur_x = 0;              /* current x in Pell iteration            */
static seq_t cur_y = 0;              /* current y in Pell iteration            */
static unsigned long long cur_step = 0; /* number of Pell steps performed         */

/* Grow the cache to accommodate at least new_len elements. */
static void grow_cache(size_t new_len)
{
    if (new_len <= cache_cap) return;
    size_t new_cap = cache_cap == 0 ? 16 : cache_cap * 2;
    while (new_cap < new_len) new_cap *= 2;
    cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    cache_cap = new_cap;
}

seq_t a(idx_t n)
{
    /* Ensure n >= 1 (offset 1). */
    if (n == 0) return (seq_t)0;

    /* Initialisation: first term a(1) = 9 (3^2). */
    if (cache_len == 0) {
        grow_cache(16);
        /* First solution (x, y) = (27, 3). */
        cur_x = (seq_t)27;
        cur_y = (seq_t)3;
        cur_step = 0;
        cache[0] = cur_y * cur_y;
        cache_len = 1;
    }

    /* Extend cache until it contains at least n terms. */
    while (cache_len < (size_t)n) {
        /* Next solution of Pell: (x', y') = (9*x + 80*y, x + 9*y) */
        seq_t tmp_x = (seq_t)9 * cur_x + (seq_t)80 * cur_y;
        seq_t tmp_y = cur_x + (seq_t)9 * cur_y;
        cur_x = tmp_x;
        cur_y = tmp_y;
        cur_step++;

        /* Store y^2 on every second step (cur_step % 2 == 0). */
        if ((cur_step & 1) == 0) {
            seq_t val = cur_y * cur_y;
            grow_cache(cache_len + 1);
            cache[cache_len++] = val;
        }
    }

    return cache[(size_t)n - 1];
}
